package com.primehr.rewardsrecognition.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.math.*;
@Entity @Table(name="rr_criterion_rating",uniqueConstraints=@UniqueConstraint(name="uk_rr_rating_criterion",columnNames={"agency_id","assignment_id","criterion_id"}))
public class RrCriterionRating extends RspAuditedEntity{@Column(name="assignment_id",nullable=false,length=36)private String assignmentId;@Column(name="criterion_id",nullable=false,length=36)private String criterionId;@Column(name="criterion_code",nullable=false,length=80)private String criterionCode;@Column(name="weight_percent",nullable=false,precision=7,scale=2)private BigDecimal weightPercent;@Column(name="maximum_score",nullable=false,precision=10,scale=2)private BigDecimal maximumScore;@Column(name="raw_score",nullable=false,precision=10,scale=2)private BigDecimal rawScore;@Column(name="weighted_score",nullable=false,precision=10,scale=4)private BigDecimal weightedScore;@Column(nullable=false,length=3000)private String comments;protected RrCriterionRating(){}public RrCriterionRating(String a,String assignment,RrAwardCriterion criterion,BigDecimal raw,String comments){super(a);if(raw==null||raw.signum()<0||raw.compareTo(criterion.getMaximumScore())>0)throw new IllegalArgumentException("Criterion score is outside the configured range");assignmentId=requiredText(assignment,"assignmentId");criterionId=criterion.getId();criterionCode=criterion.getCode();weightPercent=criterion.getWeightPercent();maximumScore=criterion.getMaximumScore();rawScore=raw;weightedScore=raw.divide(maximumScore,8,RoundingMode.HALF_UP).multiply(weightPercent).setScale(4,RoundingMode.HALF_UP);this.comments=requiredText(comments,"comments");}public String getAssignmentId(){return assignmentId;}public String getCriterionId(){return criterionId;}public String getCriterionCode(){return criterionCode;}public BigDecimal getWeightPercent(){return weightPercent;}public BigDecimal getMaximumScore(){return maximumScore;}public BigDecimal getRawScore(){return rawScore;}public BigDecimal getWeightedScore(){return weightedScore;}public String getComments(){return comments;}}
